#!/usr/bin/env python3
from ta_emss import ta_emss
import time

CELL_ID_START = 5
SIM_SERVED_AMF_ID_START = 2

if __name__ == "__main__":

    emss = ta_emss()

    emss.setup_emss(user='vcu1', bts_ip='192.168.100.129', oam_ip='192.168.100.1/24', alias='cu1')
    emss.setup_emss(user='vdu1', bts_ip='192.168.255.129', oam_ip='192.168.255.1/24', alias='du1')

    mrbts_id = emss.get_object_id('MRBTS', alias='cu1')

    # --- SETUP XTERM PARAMS ---
    print("Setting up...")
    emss.xterm_setup(
        # --- XNAP PARAMS ---
        connections_gnb={"10.0.12.10": {"ip_begin": "10.0.12.21",
                                        "ip_end": "10.0.12.22",
                                        "ip_mask": "24"}},
        gnbsim_eth_if="eth8",
        init_gnb_gnb_id=6003,
        init_gnb_mcc="311",
        init_gnb_mnc="489",
        # --- F1AP PARAMS ---
        connections_vdu={"172.16.1.101": {"ip_begin": "10.0.1.151",
                                          "ip_end": "10.0.1.152",
                                          "ip_mask": "24"}},
        vdusim_eth_if="eth3",
        init_vdu_gnb_du_id=2,
        init_vdu_frequency_band=85,
        init_vdu_num_cells=1,
        init_vdu_cell_id_begin=CELL_ID_START,
        init_vdu_ul_arfcn=139800,
        init_vdu_dl_arfcn=145800,
        init_vdu_tac=280,
        init_vdu_mcc="311",
        init_vdu_mnc="489",
        init_vdu_cell_dep_type='SA',
        # --- NGAP PARAMS ---
        connections_amf={"10.0.11.10": {"ip_begin": "10.0.11.27",
                                        "ip_end": "10.0.11.30",
                                        "ip_mask": "24",
                                        "amf_mcc": "311",
                                        "amf_mnc": "489"}},
        amf_eth_if="eth3",
        # --- IPSEC PARAMS ---
        bts_oam_ip_addr="192.168.100.129",
        # bts_ngap_ip_addr="10.0.11.10", NGAP IP addres is necessary, but is already provided in connections_amf
        ipsec_f1=True,  # necessary for IPSEC mocs for F1 and IPSEC tunnels
        ipsec_xn=True,  # necessary for IPSEC mocs for XN and IPSEC tunnels
        ipsec_ng=True,  # necessary for IPSEC mocs for NG
        ipsec_policy_order_num_begin=2,
        # --- XTERM OPTIONS ---
        verbose=True,
        debug=False
    )

    # # --- CONFIGURE AMF MOCS ---
    configure_amf_mocs_command = []
    for served_amf_id, amf_params in enumerate(emss.xterm_get("amfs"), start=SIM_SERVED_AMF_ID_START):
        configure_amf_mocs_command.append({'MOC': 'SERVEDAMF', 'ID': served_amf_id,
                                           'amfIPAddress': amf_params['AMF_IP_ADDR']})
    emss.configure_bts(configure_amf_mocs_command, skip_np=False, alias='cu1')
    time.sleep(5)

    # --- START NGAP SIMULATION ---
    print("Starting NGAP...")
    emss.xterm_start(ngap=True)
    time.sleep(5)

    # --- CONFIGURE XNAP MOCS ---
    configure_mocs_command = []

    for gnb_id, gnb in enumerate(emss.xterm_get("gnbs"), start=1):
        moc_id = str(gnb_id)
        configure_mocs_command.append({'MOC': 'XNLINK', 'ID': moc_id, 'cPlaneIpAddr': gnb['IP_ADDR']})
        configure_mocs_command.append(
            {'MOC': 'NRADJGNB', 'ID': moc_id, 'gNodeBId': str(gnb['GNB_ID']), "administrativeState": "Unlocked",
             'gnbPlmn': [{"mcc": gnb['MCC'], "mnc": gnb['MNC'], "mncLength": str(len(gnb['MNC']))}]})

    # --- CONFIGURE F1AP MOCS ---
    cell_id_start = CELL_ID_START
    dl_arfcn = emss.xterm_get("vdus")[0]['DL_ARFCN']
    ul_arfcn = emss.xterm_get("vdus")[0]['UL_ARFCN']

    for vdu in emss.xterm_get("vdus"):
        vdu['DL_ARFCN'] = dl_arfcn
        vdu['UL_ARFCN'] = ul_arfcn
        du_id = vdu['GNB_DU_ID']
        cell_group_list = []
        for cell in vdu['SERVED_CELLS']:
            configure_mocs_command.append({'MOC': 'NRCELL', 'ID': str(cell_id_start),
                                           'a1MeashoEnabledSA': 'rsrp',
                                           'a1MeashoSsbRsrpSA': [{'a1HysteresishoSsbRsrpSA': 0,
                                                                  'a1ThresholdhoSsbRsrpSA': 60,
                                                                  'a1TimeToTriggerhoSsbRsrpSA': 'ms480'
                                                                  }],
                                           'a2MeashoEnabledSA': 'rsrp',
                                           'a2MeashoSsbRsrpSA': [{'a2HysteresishoSsbRsrpSA': '0',
                                                                  'a2ThresholdhoSsbRsrpSA': '34',
                                                                  'a2TimeToTriggerhoSsbRsrpSA': 'ms480'
                                                                  }],
                                           'cellReselectionPriority': '0',
                                           'cellDepType': vdu['CELL_DEP_TYPE'],
                                           'filterCoeffSsbRsrp': 'fc4',
                                           'filterCoeffSsbRsrq': 'fc4',
                                           'nrSysInfoProfileDN': 'MRBTS-1/NRBTS-1/NRSYSINFO_PROFILE-1',
                                           'trackingAreaDN': 'MRBTS-1/NRBTS-1/TRACKINGAREA-1',
                                           'freqBandIndicatorNR': vdu['FREQUENCY_BAND'],
                                           'lcrId': str(cell_id_start),
                                           'physCellId': cell['PCI'],
                                           'allowUnsuppBcOrBcs': ['accept unknown band combinations'],
                                           'chBw': '50MHz',
                                           'drxProfileNrAnr': [
                                               {'drxControl': 'any', 'nrDrxDN': 'MRBTS-1/NRBTS-1/NRDRX-3'}],
                                           'rlfPsccTrigThresholdRsrp': '42',
                                           'a1MeashoEnabled': 'none',
                                           'a2MeashoEnabled': 'none',
                                           'cellTechnology': 'FDD',
                                           'ssPbchBlockPower': '10',
                                           'actDataForwardingForVoNr': 'deactivated'
                                           })
            configure_mocs_command.append({'MOC': 'NRCELL_FDD', 'ID': f'{cell_id_start}-1',
                                           'chBwDl': '5MHz',
                                           'chBwUl': '5MHz',
                                           'nrarfcnDl': dl_arfcn,
                                           'nrarfcnUl': ul_arfcn
                                           })
            configure_mocs_command.append({'MOC': 'NRCELLGRP', 'ID': str(cell_id_start),
                                           'scs': '15 KHz',
                                           'nrCellList': [cell_id_start]
                                           })
            cell_group_list.append(cell_id_start)
            cell_id_start += 1

        configure_mocs_command.append({'MOC': 'NRDU', 'ID': du_id,
                                       'actConnectedModeMobilityCA': 'true',
                                       'actInterNumerologyCa': 'true',
                                       'carrierAggregationSupportList': ['ca_Fr1Tdd_Any_Sa', 'ca_Fr1Tdd_Fdd_Sa',
                                                                         'ca_Fr1Tdd_Sa'],
                                       'flexibleCAMode': 'ConfigurationIndependent',
                                       'gNbDuId': du_id,
                                       'gNbDuName': f'VDU_{du_id}',
                                       'refNrCellGroup': cell_group_list,
                                       'remoteDuIpAddr': vdu['IP_ADDR']},
                                      )
        dl_arfcn += 20
        ul_arfcn += 20
    emss.configure_bts(configure_mocs_command, skip_np=False, alias='cu1')
    time.sleep(15)

    # --- START F1AP SIMULATION ---
    print("Starting...")
    emss.xterm_start(f1ap=True, xnap=True)
    time.sleep(30)

    # --- CONFIGURE AND START IPSEC ---
    emss.xterm_configure_ipsec(alias='cu1')

    # --- BREAK SIMULATION ---
    while (k := input("Press 'q' to stop...")) != 'q':
        pass
    emss.xterm_deconfigure_ipsec()

    # --- DELETE PREVIOUSLY ADDED MOCS ---
    delete_moc_command = []
    print("Deleting previously added SERVEDAMF MOC")
    for amf_id, amf in enumerate(emss.xterm_get("amfs"), start=SIM_SERVED_AMF_ID_START):
        delete_moc_command.append({'DEL': 'SERVEDAMF', 'ID': amf_id})

    print("Deleting previously added NRDU, NRCELL, NRCELLGRP, XNLINK moc")
    number_of_vdus = len(emss.xterm_get("vdus"))
    number_of_cell_per_vdu = len(emss.xterm_get("vdus")[0]['SERVED_CELLS'])

    for vdu in emss.xterm_get("vdus"):
        delete_moc_command.append({'DEL': 'NRDU', 'ID': vdu['GNB_DU_ID']})
    for moc_id in range(CELL_ID_START, CELL_ID_START + number_of_vdus * number_of_cell_per_vdu):
        delete_moc_command.append({'DEL': 'NRCELLGRP', 'ID': moc_id})
        delete_moc_command.append({'DEL': 'NRCELL', 'ID': moc_id})
    for gnb_id, gnb in enumerate(emss.xterm_get("gnbs"), start=1):
        delete_moc_command.append({'DEL': 'XNLINK', 'ID': str(gnb_id)})
        delete_moc_command.append({'DEL': 'NRADJGNB', 'ID': str(gnb_id)})
        # --- DELETE IPSEC MOCS ---
    print("DELETE IPSEC MOCS")
    delete_moc_command.append({'DEL': 'IPAPP', 'ID': '1-2-1'})

    emss.configure(delete_moc_command, alias='cu1')

    # --- STOP XTERM ---
    print("Stopping xterm")
    emss.xterm_teardown()
